input.command:
export SB=/probe/sb_state; /probe/reset.sh
mkdir -p $SB/v; ( /probe/jt.sh vault a $SB/v >/dev/null 2>&1 )
V=$SB/home/.local/share/jot/vaults
echo "### no current; run list from INSIDE vault dir"; ( cd $SB/v/a && /probe/jt.sh list 2>&1 | cat -A )
echo "### no current; run note from INSIDE vault dir"; ( cd $SB/v/a && /probe/jt.sh note zz 2>&1 | cat -A )
echo "### tree: $(find $SB/v|sort|tr '\n' ' ')"
( cd /workspace && /probe/jt.sh enter a >/dev/null 2>&1 )
( cd /workspace && /probe/jt.sh folder sub >/dev/null 2>&1 )
echo "### current=a, folder=''; run 'note fromsub' while cwd=\$SB/v/a/sub"; ( cd $SB/v/a/sub && /probe/jt.sh note fromsub 2>&1|cat -A )
echo "### tree: $(find $SB/v|sort|tr '\n' ' ')"
echo "### run from /  "; ( cd / && /probe/jt.sh list 2>&1|cat -A )
echo "### run from /tmp"; ( cd /tmp && /probe/jt.sh list 2>&1|cat -A )
echo "### data: $(cat $SB/v/a/.jot/data|tr '\n' '|')"
echo "### deleted cwd"; mkdir -p /tmp/gone; ( cd /tmp/gone && rmdir /tmp/gone && /probe/jt.sh list 2>&1|cat -A )
